CREATE TABLE badge_definitions(id UUID PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description VARCHAR(1000) NOT NULL,condition_json TEXT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE xp_rules(id UUID PRIMARY KEY,action VARCHAR(120) NOT NULL UNIQUE,xp_amount INTEGER NOT NULL CHECK(xp_amount>0),frequency_limit INTEGER,daily_limit INTEGER,conditions_json TEXT NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE reward_definitions(id UUID PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,type VARCHAR(40) NOT NULL,value NUMERIC(19,4) NOT NULL CHECK(value>=0),xp_cost INTEGER NOT NULL CHECK(xp_cost>=0),stock INTEGER,currency VARCHAR(3),status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE mission_fraud_alerts(id UUID PRIMARY KEY,user_id VARCHAR(120) NOT NULL,rule VARCHAR(120) NOT NULL,severity VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,evidence_json TEXT NOT NULL,source_reference VARCHAR(180) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_fraud_alert_queue ON mission_fraud_alerts(status,severity,created_at DESC);
CREATE INDEX idx_fraud_alert_user ON mission_fraud_alerts(user_id,created_at DESC);
